From 2e09bd42ec2777b9b37e0b98254e295e95673d0a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 16:10:38 +0100
Subject: [PATCH] oom_notifier: Name D-Bus activated applications

The notification showed the raw unit name of D-Bus activated apps, like
dbus-:1.2-org.kde.yakuake@0.service, since only app-* units were mapped
to a desktop entry. Map dbus-broker's units to their bus name as well.

BUG: 510234
---
 components/systemd_decode.h | 22 ++++++++++++++++++++--
 1 file changed, 20 insertions(+), 2 deletions(-)

diff --git a/components/systemd_decode.h b/components/systemd_decode.h
index d22c093a35..7e17700d7c 100644
--- a/components/systemd_decode.h
+++ b/components/systemd_decode.h
@@ -81,12 +81,30 @@ inline QStringView unitNameToServiceName(QStringView unitName)
 {
     Q_ASSERT_X(!unitName.contains(QLatin1Char('/')), Q_FUNC_INFO, unitName.toUtf8().constData());

+    constexpr auto separator = QLatin1Char('-');
+
+    // Services activated by dbus-broker without a SystemdService= are named
+    // dbus-<unique name>-<well-known name>@<n>.service, e.g. dbus-:1.2-org.kde.yakuake@0.service.
+    // The well-known name is often also the desktop file name.
+    if (constexpr QLatin1String dbusPrefix("dbus-:"); unitName.startsWith(dbusPrefix)) {
+        // Unique bus names cannot contain a '-', so the next one starts the well-known name
+        const auto separatorIndex = unitName.indexOf(separator, dbusPrefix.size());
+        if (separatorIndex < 0) {
+            return {};
+        }
+        auto name = unitName.mid(separatorIndex + 1);
+        if (auto index = name.lastIndexOf(QLatin1Char('@')); index >= 0) {
+            name.truncate(index);
+        } else if (name.endsWith(QLatin1String(".service"))) {
+            name.chop(QLatin1String(".service").size());
+        }
+        return name;
+    }
+
     if (!unitName.startsWith(QLatin1String("app-"))) {
         return {};
     }

-    constexpr auto separator = QLatin1Char('-');
-
     // Always chop the app- prefix off
     auto name = unitName.mid(unitName.indexOf(separator) + 1);
     // Sometimes chop the @uuid.scope suffix off
-- 
